const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();
pres.layout = 'LAYOUT_WIDE';

// Slide 1: Title
const s1 = pres.addSlide();
s1.addText('团队协作', { x: 0.8, y: 1.5, w: 11, fontSize: 44, bold: true, color: '1B4F72', fontFace: '微软雅黑' });
s1.addText('打造高效、信任、共赢的团队', { x: 0.8, y: 2.8, w: 11, fontSize: 22, color: '555555', fontFace: '微软雅黑' });

// Slide 2: Why teamwork matters
const s2 = pres.addSlide();
s2.addText('为什么团队协作至关重要', { x: 0.6, y: 0.4, w: 11, fontSize: 28, bold: true, color: '1B4F72', fontFace: '微软雅黑' });
s2.addText('• 复杂问题需要多元视角与跨职能能力\n• 协作能将个人产出放大为系统成果\n• 高信任团队决策更快、试错成本更低\n• 员工在协作环境中敬业度提升 30%+', { x: 0.6, y: 1.3, w: 11, fontSize: 18, color: '333333', fontFace: '微软雅黑', lineSpacingMultiple: 1.5 });

// Slide 3: Core principles
const s3 = pres.addSlide();
s3.addText('高效协作的四大支柱', { x: 0.6, y: 0.4, w: 11, fontSize: 28, bold: true, color: '1B4F72', fontFace: '微软雅黑' });
s3.addText('1. 共同目标 — 对齐愿景，减少方向摩擦\n2. 透明沟通 — 信息对称，避免重复劳动\n3. 角色清晰 — 权责明确，杜绝灰色地带\n4. 心理安全 — 鼓励发声，让好想法不被埋没', { x: 0.6, y: 1.3, w: 11, fontSize: 18, color: '333333', fontFace: '微软雅黑', lineSpacingMultiple: 1.5 });

// Slide 4: Practical methods
const s4 = pres.addSlide();
s4.addText('落地实践方法', { x: 0.6, y: 0.4, w: 11, fontSize: 28, bold: true, color: '1B4F72', fontFace: '微软雅黑' });
s4.addText('• 每日站会 15 分钟：同步进展 + 暴露阻塞\n• 共享文档 & 看板：让进度可见、可追溯\n• RACI 矩阵：谁负责 / 谁审批 / 谁咨询 / 谁知会\n• 定期复盘（Retrospective）：持续改进而非追责\n• 异步优先：减少会议依赖，保留深度工作时间', { x: 0.6, y: 1.3, w: 11, fontSize: 18, color: '333333', fontFace: '微软雅黑', lineSpacingMultiple: 1.4 });

// Slide 5: Summary & call to action
const s5 = pres.addSlide();
s5.addText('从今天开始行动', { x: 0.6, y: 0.4, w: 11, fontSize: 28, bold: true, color: '1B4F72', fontFace: '微软雅黑' });
s5.addText('✓ 本周发起一次 15 分钟团队复盘\n✓ 建立或更新团队的 RACI 矩阵\n✓ 选一个工具统一信息源（文档/看板/频道）\n✓ 下次会议预留 5 分钟"开放提问"环节\n\n协作不是天赋，是习惯。从小事做起，持续积累信任。', { x: 0.6, y: 1.3, w: 11, fontSize: 18, color: '333333', fontFace: '微软雅黑', lineSpacingMultiple: 1.4 });

pres.writeFile({ fileName: '/workspace/团队协作.pptx' }).then(() => console.log('done'));
